import{_ as o,c as l,a2 as a,o as i}from"./chunks/framework.CqbvlPrP.js";const d=JSON.parse('{"title":"第一千二百章 善知识等品 增支部1集71经到80经","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/1200第一千二百章 善知识等品 增支部1集71经到80经.md","filePath":"meditation/巴利文大藏经/1200第一千二百章 善知识等品 增支部1集71经到80经.md"}'),p={name:"meditation/巴利文大藏经/1200第一千二百章 善知识等品 增支部1集71经到80经.md"};function e(r,t,_,s,u,n){return i(),l("div",null,t[0]||(t[0]=[a('<h1 id="第一千二百章-善知识等品-增支部1集71经到80经" tabindex="-1">第一千二百章 善知识等品 增支部1集71经到80经 <a class="header-anchor" href="#第一千二百章-善知识等品-增支部1集71经到80经" aria-label="Permalink to &quot;第一千二百章 善知识等品 增支部1集71经到80经&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>增支部1集71经到80经</p><p>71经</p><ol start="71"><li>&quot;比丘们，我不见有任何其他单一法，能使未生起的善法生起，已生起的不善法衰减，如同这个，比丘们，即善知识。比丘们，对于有善知识的人，未生起的善法便会生起，已生起的不善法便会衰减。&quot;这是第一经。</li></ol><p>72经</p><ol start="72"><li>&quot;比丘们，我不见有任何其他单一法，能使未生起的不善法生起，已生起的善法衰减，如同这个，比丘们，即从事不善法，不从事善法。比丘们，由于从事不善法，不从事善法，未生起的不善法便会生起，已生起的善法便会衰减。&quot;这是第二经。</li></ol><p>73经</p><ol start="73"><li>&quot;比丘们，我不见有任何其他单一法，能使未生起的善法生起，已生起的不善法衰减，如同这个，比丘们，即从事善法，不从事不善法。比丘们，由于从事善法，不从事不善法，未生起的善法便会生起，已生起的不善法便会衰减。&quot;这是第三经。</li></ol><p>74经</p><ol start="74"><li>&quot;比丘们，我不见有任何其他单一法，能使未生起的觉支不生起，已生起的觉支不达到修习圆满，如同这个，比丘们，即不如理作意。比丘们，由于不如理作意，未生起的觉支便不会生起，已生起的觉支便不会达到修习圆满。&quot;这是第四经。</li></ol><p>75经</p><ol start="75"><li>&quot;比丘们，我不见有任何其他单一法，能使未生起的觉支生起，已生起的觉支达到修习圆满，如同这个，比丘们，即如理作意。比丘们，由于如理作意，未生起的觉支便会生起，已生起的觉支便会达到修习圆满。&quot;这是第五经。</li></ol><p>76经</p><ol start="76"><li>&quot;比丘们，这是微小的衰减，即亲属的衰减。比丘们，这是最劣等的衰减，即智慧的衰减。&quot;这是第六经。</li></ol><p>77经</p><ol start="77"><li>&quot;比丘们，这是微小的增长，即亲属的增长。比丘们，这是最上等的增长，即智慧的增长。因此，比丘们，你们应当如此学习：&#39;我们将以智慧的增长而增长。&#39;比丘们，你们应当如此学习。&quot;这是第七经。</li></ol><p>78经</p><ol start="78"><li>&quot;比丘们，这是微小的衰减，即财富的衰减。比丘们，这是最劣等的衰减，即智慧的衰减。&quot;这是第八经。</li></ol><p>79经</p><ol start="79"><li>&quot;比丘们，这是微小的增长，即财富的增长。比丘们，这是最上等的增长，即智慧的增长。因此，比丘们，你们应当如此学习：&#39;我们将以智慧的增长而增长。&#39;比丘们，你们应当如此学习。&quot;这是第九经。</li></ol><p>80经</p><ol start="80"><li>&quot;比丘们，这是微小的衰减，即名声的衰减。比丘们，这是最劣等的衰减，即智慧的衰减。&quot;这是第十经。</li></ol><p>善知识等品第八结束。</p>',24)]))}const c=o(p,[["render",e]]);export{d as __pageData,c as default};
